import 'dart:convert';
import 'dart:typed_data';

import 'package:meshcore_link/meshcore_link.dart';
import 'package:test/test.dart';

// Independent application vectors, not generated by either codec under test.
const _nonce = [
  0x00,
  0x11,
  0x22,
  0x33,
  0x44,
  0x55,
  0x66,
  0x77,
  0x88,
  0x99,
  0xaa,
  0xbb,
  0xcc,
  0xdd,
  0xee,
  0xff,
];
const _content = [0x00, 0x3c, 0x80, 0xff];
const _ping = [
  0x4d,
  0x43,
  0x48,
  0x50,
  0x01,
  0x01,
  0x00,
  0x11,
  0x22,
  0x33,
  0x44,
  0x55,
  0x66,
  0x77,
  0x88,
  0x99,
  0xaa,
  0xbb,
  0xcc,
  0xdd,
  0xee,
  0xff,
  0x78,
  0x56,
  0x34,
  0x12,
  0xef,
  0xcd,
  0xab,
  0x89,
  0x04,
  0x03,
  0x02,
  0xf1,
  0x00,
  0x3c,
  0x80,
  0xff,
];
const _pong = [
  0x4d,
  0x43,
  0x48,
  0x50,
  0x01,
  0x02,
  0x00,
  0x11,
  0x22,
  0x33,
  0x44,
  0x55,
  0x66,
  0x77,
  0x88,
  0x99,
  0xaa,
  0xbb,
  0xcc,
  0xdd,
  0xee,
  0xff,
  0x78,
  0x56,
  0x34,
  0x12,
  0x04,
  0x03,
  0x02,
  0xf1,
  0xef,
  0xcd,
  0xab,
  0x89,
  0x00,
  0x3c,
  0x80,
  0xff,
];
const _a = 0x89abcdef;
const _b = 0xf1020304;

void main() {
  group('diagnostic v1 vectors and model', () {
    test('encodes independent PING and PONG vectors', () {
      expect(encodeDiagnosticPayload(message()), _ping);
      expect(
        encodeDiagnosticPayload(
          message(kind: DiagnosticKind.pong, sender: _b, target: _a),
        ),
        _pong,
      );
    });

    test('decodes independent vectors with little-endian high uint32 IDs', () {
      for (final (bytes, kind, sender, target) in [
        (_ping, DiagnosticKind.ping, _a, _b),
        (_pong, DiagnosticKind.pong, _b, _a),
      ]) {
        final result = decodeDiagnosticPayload(Uint8List.fromList(bytes));
        expect(result.status, DiagnosticDecodeStatus.valid);
        expect(result.reason, isNull);
        final decoded = result.message!;
        expect(decoded.version, 1);
        expect(decoded.kind, kind);
        expect(decoded.runNonce, _nonce);
        expect(decoded.requestId, 0x12345678);
        expect(decoded.senderTestId, sender);
        expect(decoded.targetTestId, target);
        expect(decoded.content, _content);
      }
    });

    test('accepts ID endpoints and arbitrary nonce bytes in round trips', () {
      for (final (request, sender, target) in [
        (1, 1, 0xffffffff),
        (0xffffffff, 0xffffffff, 1),
      ]) {
        final original = message(
          request: request,
          sender: sender,
          target: target,
          nonce: Uint8List(16),
          content: Uint8List(0),
        );
        final encoded = encodeDiagnosticPayload(original);
        expect(encoded.length, 34);
        final decoded = decodeDiagnosticPayload(encoded).message!;
        expect(decoded.runNonce, List.filled(16, 0));
        expect(decoded.requestId, request);
        expect(decoded.senderTestId, sender);
        expect(decoded.targetTestId, target);
        expect(decoded.content, isEmpty);
        expect(encodeDiagnosticPayload(decoded), encoded);
      }
    });

    test('rejects invalid IDs, equal endpoints, and non-16-byte nonces', () {
      for (final id in [-1, 0, 0x100000000]) {
        for (final create in [
          () => message(request: id),
          () => message(sender: id),
          () => message(target: id),
        ]) {
          expect(create, throwsArgumentError);
        }
      }
      expect(() => message(sender: _a, target: _a), throwsArgumentError);
      for (final length in [0, 15, 17]) {
        expect(() => message(nonce: Uint8List(length)), throwsArgumentError);
      }
    });
  });

  group('diagnostic classification', () {
    test('checks outer data type before application magic', () {
      for (final bytes in [_ping, <int>[]]) {
        expectFailure(
          classifyDiagnosticDatagram(received(bytes, type: 0x1234)),
          DiagnosticDecodeStatus.unrelated,
          DiagnosticDecodeReason.differentDataType,
        );
      }
      expect(
        classifyDiagnosticDatagram(received(_ping)).message!.kind,
        DiagnosticKind.ping,
      );
    });

    test('incomplete or different magic is unrelated', () {
      for (var length = 0; length < 4; length++) {
        expectFailure(
          decodeDiagnosticPayload(
            Uint8List.fromList(_ping.take(length).toList()),
          ),
          DiagnosticDecodeStatus.unrelated,
          DiagnosticDecodeReason.differentMagic,
        );
      }
      for (var offset = 0; offset < 4; offset++) {
        expectFailure(
          decodeDiagnosticPayload(Uint8List.fromList(_ping)..[offset] = 0),
          DiagnosticDecodeStatus.unrelated,
          DiagnosticDecodeReason.differentMagic,
        );
      }
    });

    test('gates version and kind before interpreting the v1 header', () {
      for (final (bytes, status, reason) in [
        (
          _ping.take(4).toList(),
          DiagnosticDecodeStatus.malformed,
          DiagnosticDecodeReason.truncated,
        ),
        (
          _ping.take(5).toList(),
          DiagnosticDecodeStatus.malformed,
          DiagnosticDecodeReason.truncated,
        ),
        (
          [..._ping.take(4), 2],
          DiagnosticDecodeStatus.unsupported,
          DiagnosticDecodeReason.unsupportedVersion,
        ),
        (
          [..._ping.take(4), 2, ...List.filled(200, 0)],
          DiagnosticDecodeStatus.unsupported,
          DiagnosticDecodeReason.unsupportedVersion,
        ),
        (
          [..._ping.take(5), 3],
          DiagnosticDecodeStatus.unsupported,
          DiagnosticDecodeReason.unsupportedKind,
        ),
        (
          [..._ping.take(5), 0, ...List.filled(200, 0)],
          DiagnosticDecodeStatus.unsupported,
          DiagnosticDecodeReason.unsupportedKind,
        ),
      ]) {
        expectFailure(
          decodeDiagnosticPayload(Uint8List.fromList(bytes)),
          status,
          reason,
        );
      }
      for (var length = 6; length < 34; length++) {
        expectFailure(
          decodeDiagnosticPayload(
            Uint8List.fromList(_ping.take(length).toList()),
          ),
          DiagnosticDecodeStatus.malformed,
          DiagnosticDecodeReason.truncated,
        );
      }
    });

    test(
      'known v1 rejects excessive length, zero IDs, and equal endpoints',
      () {
        expectFailure(
          decodeDiagnosticPayload(
            Uint8List.fromList([..._ping, ...List.filled(128, 0)]),
          ),
          DiagnosticDecodeStatus.malformed,
          DiagnosticDecodeReason.payloadTooLong,
        );
        for (final offset in [22, 26, 30]) {
          final bytes = Uint8List.fromList(_ping);
          ByteData.sublistView(bytes).setUint32(offset, 0, Endian.little);
          expectFailure(
            decodeDiagnosticPayload(bytes),
            DiagnosticDecodeStatus.malformed,
            DiagnosticDecodeReason.invalidId,
          );
        }
        final equal = Uint8List.fromList(_ping);
        ByteData.sublistView(equal).setUint32(30, _a, Endian.little);
        expectFailure(
          decodeDiagnosticPayload(equal),
          DiagnosticDecodeStatus.malformed,
          DiagnosticDecodeReason.identicalEndpoints,
        );
      },
    );

    test('Companion entries remain typed and ordinary chat is only a summary', () {
      // The helper passes a legal device-direction inner frame through the real
      // Companion decoder; no private response constructor is exposed.
      final datagram = received(_pong, channel: 2);
      expect(datagram.channelIndex, 2);
      expect(datagram.dataType, 0xffff);
      expect(
        classifyDiagnosticDatagram(datagram).message!.kind,
        DiagnosticKind.pong,
      );
      final chatFrame = Uint8List.fromList([
        0x08,
        5,
        0,
        0,
        0,
        0,
        0,
        0,
        ...utf8.encode('CHAT_SECRET'),
        ..._pong,
      ]);
      final chat = decodeCompanionResponse(chatFrame);
      expect(chat, isA<QueuedMessageResponse>());
      expect(chat, isNot(isA<ChannelDataResponse>()));
      expect(
        (chat as QueuedMessageResponse).kind,
        QueuedMessageKind.legacyChannelText,
      );
      expect(chat.contentLength, chatFrame.length);
      expect(chat.toString(), isNot(contains('CHAT_SECRET')));
    });
  });

  group('diagnostic content and route budgets', () {
    test('global encoding preserves empty and maximum binary content', () {
      expect(
        encodeDiagnosticPayload(message(content: Uint8List(0))).length,
        34,
      );
      final content = Uint8List.fromList(List.generate(131, (i) => 255 - i));
      final encoded = encodeDiagnosticPayload(message(content: content));
      expect(encoded.length, 165);
      expect(decodeDiagnosticPayload(encoded).message!.content, content);
      expect(
        () => encodeDiagnosticPayload(message(content: Uint8List(132))),
        throwsArgumentError,
      );
    });

    test(
      'content wrapper and sender agree for Flood and Direct boundaries',
      () {
        for (final (descriptor, pathLength, capacity) in [
          (0xff, 0, 131),
          (0, 0, 131),
          (0x60, 64, 73),
        ]) {
          final path = Uint8List(pathLength);
          expect(
            maxDiagnosticContentLengthForRoute(
              routeDescriptor: descriptor,
              path: path,
            ),
            capacity,
          );
          final payload = encodeDiagnosticPayload(
            message(content: Uint8List(capacity)),
          );
          expect(payload.length, capacity + 34);
          expect(
            encodeSendChannelData(
              channelIndex: 2,
              dataType: diagnosticDataType,
              routeDescriptor: descriptor,
              path: path,
              payload: payload,
            ).length,
            5 + pathLength + payload.length,
          );
        }
        // This fits the global application limit but not this outbound path.
        final tooLong = encodeDiagnosticPayload(
          message(content: Uint8List(74)),
        );
        expect(
          decodeDiagnosticPayload(tooLong).status,
          DiagnosticDecodeStatus.valid,
        );
        expect(
          () => encodeSendChannelData(
            channelIndex: 2,
            dataType: diagnosticDataType,
            routeDescriptor: 0x60,
            path: Uint8List(64),
            payload: tooLong,
          ),
          throwsArgumentError,
        );
      },
    );
  });

  group('pure PONG construction and matching', () {
    test(
      'exchanges labels and echoes bytes with different local channel slots',
      () {
        final response = createDiagnosticPong(
          datagram: received(_ping, channel: 5, routeMetadata: 0x42),
          expectedReceiveChannelIndex: 5,
          localTestId: _b,
          peerTestId: _a,
        )!;
        expect(encodeDiagnosticPayload(response), _pong);
        final expected = message(); // Separately allocated nonce and content.
        expect(identical(expected.runNonce, response.runNonce), isFalse);
        expect(identical(expected.content, response.content), isFalse);
        expect(
          matchesDiagnosticPong(
            expectedPing: expected,
            datagram: received(encodeDiagnosticPayload(response), channel: 2),
            expectedReceiveChannelIndex: 2,
          ),
          isTrue,
        );
      },
    );

    test(
      'ignores other slots, peers, targets, kinds, and application formats',
      () {
        for (final (datagram, local, peer) in [
          (received(_ping, channel: 2), _b, _a),
          (received(_ping), _b, 3),
          (received(_ping), 3, _a),
          (received(_pong), _b, _a),
          (received(_ping, type: 1), _b, _a),
          (received(const []), _b, _a),
          (received([..._ping.take(4), 2]), _b, _a),
          (received([..._ping.take(5), 3]), _b, _a),
          (received(_ping.take(33).toList()), _b, _a),
        ]) {
          expect(
            createDiagnosticPong(
              datagram: datagram,
              expectedReceiveChannelIndex: 5,
              localTestId: local,
              peerTestId: peer,
            ),
            isNull,
          );
        }
      },
    );

    test('matches every field by value, including exact content length', () {
      final expected = message();
      final variants = <String, ChannelDataResponse>{
        'channel': received(_pong, channel: 5),
        'data type': received(_pong, channel: 2, type: 1),
        'empty payload': received(const [], channel: 2),
      };
      for (final (name, offset, value) in [
        ('magic', 0, 0),
        ('version', 4, 2),
        ('kind', 5, 1),
        ('nonce', 6, 1),
        ('request', 22, 1),
        ('sender', 26, 1),
        ('target', 30, 1),
        ('content', 34, 1),
      ]) {
        variants[name] = received(
          Uint8List.fromList(_pong)..[offset] = value,
          channel: 2,
        );
      }
      final appended = [..._pong, 0];
      final longer = decodeDiagnosticPayload(Uint8List.fromList(appended));
      expect(longer.status, DiagnosticDecodeStatus.valid);
      expect(longer.message!.content, [..._content, 0]);
      variants['longer content'] = received(appended, channel: 2);
      variants['shorter content'] = received(
        _pong.take(37).toList(),
        channel: 2,
      );
      for (final entry in variants.entries) {
        expect(
          matchesDiagnosticPong(
            expectedPing: expected,
            datagram: entry.value,
            expectedReceiveChannelIndex: 2,
          ),
          isFalse,
          reason: entry.key,
        );
      }
    });

    test('rejects invalid configuration and a non-PING expected request', () {
      for (final channel in [-1, 256]) {
        expect(
          () => createDiagnosticPong(
            datagram: received(_ping),
            expectedReceiveChannelIndex: channel,
            localTestId: _b,
            peerTestId: _a,
          ),
          throwsRangeError,
        );
        expect(
          () => matchesDiagnosticPong(
            expectedPing: message(),
            datagram: received(_pong),
            expectedReceiveChannelIndex: channel,
          ),
          throwsRangeError,
        );
      }
      for (final (local, peer) in [
        (0, _a),
        (_b, -1),
        (0x100000000, _a),
        (_a, _a),
      ]) {
        expect(
          () => createDiagnosticPong(
            datagram: received(_ping),
            expectedReceiveChannelIndex: 5,
            localTestId: local,
            peerTestId: peer,
          ),
          throwsArgumentError,
        );
      }
      expect(
        () => matchesDiagnosticPong(
          expectedPing: message(kind: DiagnosticKind.pong),
          datagram: received(_pong),
          expectedReceiveChannelIndex: 5,
        ),
        throwsArgumentError,
      );
      for (final channel in [0, 255]) {
        expect(
          matchesDiagnosticPong(
            expectedPing: message(),
            datagram: received(_pong, channel: channel),
            expectedReceiveChannelIndex: channel,
          ),
          isTrue,
        );
      }
    });
  });

  group('diagnostic ownership and privacy', () {
    test(
      'construction, decoding offset views, and encoding own their bytes',
      () {
        final nonce = Uint8List.fromList(_nonce);
        final content = Uint8List.fromList(_content);
        final original = message(nonce: nonce, content: content);
        final encoded = encodeDiagnosticPayload(original);
        nonce.fillRange(0, nonce.length, 0);
        content.fillRange(0, content.length, 0);
        expect(original.runNonce, _nonce);
        expect(original.content, _content);
        expect(encoded, _ping);

        final storage = Uint8List.fromList([0xfe, 0xfd, ..._ping, 0xfc]);
        final view = Uint8List.sublistView(storage, 2, 2 + _ping.length);
        final decoded = decodeDiagnosticPayload(view).message!;
        storage.fillRange(0, storage.length, 0);
        encoded.fillRange(0, encoded.length, 0);
        for (final model in [original, decoded]) {
          expect(model.runNonce, _nonce);
          expect(model.content, _content);
          expect(encodeDiagnosticPayload(model), _ping);
          expect(() => model.runNonce[0] = 1, throwsUnsupportedError);
          expect(() => model.content[0] = 1, throwsUnsupportedError);
          expect(
            () => model.runNonce.buffer.asUint8List()[0] = 1,
            throwsUnsupportedError,
          );
          expect(
            () => model.content.buffer.asUint8List()[0] = 1,
            throwsUnsupportedError,
          );
        }
        // Bytes outside a logical view must not fill its missing header.
        expectFailure(
          decodeDiagnosticPayload(
            Uint8List.sublistView(Uint8List.fromList(_ping), 0, 4),
          ),
          DiagnosticDecodeStatus.malformed,
          DiagnosticDecodeReason.truncated,
        );
      },
    );

    test('default summaries and argument errors omit private bytes and IDs', () {
      final secretNonce = Uint8List.fromList(utf8.encode('PRIVATE_NONCE_16'));
      final secretContent = Uint8List.fromList(utf8.encode('PRIVATE_CONTENT'));
      final model = message(nonce: secretNonce, content: secretContent);
      final privatePayload = encodeDiagnosticPayload(model);
      final summaries = <String>[
        '$model',
        '${decodeDiagnosticPayload(privatePayload)}',
        '${classifyDiagnosticDatagram(received(privatePayload, type: 1))}',
        '${decodeDiagnosticPayload(privatePayload.sublist(0, 33))}',
        '${decodeDiagnosticPayload(Uint8List.fromList(privatePayload)..[4] = 2)}',
      ];
      for (final create in [
        () => message(nonce: secretNonce.sublist(1), content: secretContent),
        () => message(nonce: secretNonce, content: Uint8List(132)),
        () => message(sender: _a, target: _a),
        () => message(request: 0x100000000),
      ]) {
        try {
          create();
          fail('Invalid arguments must throw.');
        } on ArgumentError catch (error) {
          expect(error.invalidValue, isNot(isA<List<int>>()));
          summaries.add('$error');
        }
      }
      for (final summary in summaries) {
        for (final hidden in [
          'PRIVATE_NONCE_16',
          'PRIVATE_CONTENT',
          '$secretNonce',
          '$secretContent',
          '$privatePayload',
          '$_a',
          '$_b',
          '2309737967',
          '4043440900',
          '4294967296',
        ]) {
          expect(summary, isNot(contains(hidden)));
        }
      }
    });
  });
}

MeshchanDiagnosticMessage message({
  DiagnosticKind kind = DiagnosticKind.ping,
  Uint8List? nonce,
  int request = 0x12345678,
  int sender = _a,
  int target = _b,
  Uint8List? content,
}) => MeshchanDiagnosticMessage(
  kind: kind,
  runNonce: nonce ?? Uint8List.fromList(_nonce),
  requestId: request,
  senderTestId: sender,
  targetTestId: target,
  content: content ?? Uint8List.fromList(_content),
);

// Explicit outer type, local channel, receive metadata, and binary payload.
ChannelDataResponse received(
  List<int> payload, {
  int channel = 5,
  int type = 0xffff,
  int routeMetadata = 0xff,
}) {
  final frame = Uint8List.fromList([
    0x1b,
    0xf2,
    0xa5,
    0x5a,
    channel,
    routeMetadata,
    0,
    0,
    payload.length,
    ...payload,
  ]);
  ByteData.sublistView(frame).setUint16(6, type, Endian.little);
  return decodeCompanionResponse(frame) as ChannelDataResponse;
}

void expectFailure(
  DiagnosticDecodeResult result,
  DiagnosticDecodeStatus status,
  DiagnosticDecodeReason reason,
) {
  expect(result.status, status);
  expect(result.reason, reason);
  expect(result.message, isNull);
}
